/* Inserted inside the application controller by the build. */
 let finView='summary',finAccountId='BANK-1',finTitleFilter='open';
 const finCategory=key=>F.categories.find(([k])=>k===key)?.[1]||key;
 const finSigned=(value,type)=>`<span class="fin-amount ${type==='in'?'fin-in':'fin-out'}">${type==='in'?'+':'−'} ${cash(value)}</span>`;
 const finAccountOptions=()=>F.ensure(ops).accounts.map(a=>[a.id,a.name]);
 const finDriverOptions=()=>[['','Sem vínculo · selecione para caução'],...ops.drivers.map(d=>[d.id,d.name])];
 const finVehicleOptions=()=>[['company','Empresa · despesa geral'],...M.vehicles(ops).map(v=>[v.id,v.id+' · '+v.model])];
 function finTabs(){return `<div class="segments fin-tabs" aria-label="Áreas do financeiro">${[['summary','Resumo'],['titles','Pagar e receber'],['reconcile','Conciliação'],['ledger','Livro de caixa']].map(([key,label])=>`<button type="button" data-action="fin-tab" data-value="${key}" aria-pressed="${finView===key}">${label}</button>`).join('')}</div>`;}
 function finance(){const s=F.summary(ops,baseline);return heading('TESOURARIA · JANEIRO DE 2027 · FECHAMENTO EM 31/01','Cada real, do compromisso à conferência.','Organize o que entra e sai, faça a baixa e confira o extrato contra o mesmo livro da operação.',btn('Conta a receber','fin-new-receivable')+btn('Conta a pagar','fin-new-payable','primary'))+`<div class="stats">${stat('Caixa do livro',cash(s.cash),'Inclui '+cash(s.actual?.liabilities||0)+' de obrigações',true,'cash-source')}${stat('A receber',cash(s.receivable),'Títulos em aberto; comprovante não é baixa')}${stat('A pagar',cash(s.payable),'Compromissos ainda sem desembolso')}${stat('Diferença banco × livro',cash(s.difference),s.unmatchedBank+' movimento(s) de extrato a conferir')}</div><div class="gap">${rentalPanel()}</div><details class="gap"><summary>Repasses, devoluções de valores e estornos</summary>${settlementPanel()}</details>${finTabs()}<div class="gap fin-workspace">${finView==='titles'?finTitles():finView==='reconcile'?finReconciliation(s):finView==='ledger'?finLedger():finSummary(s)}</div><p class="caption">Bancos e extratos fictícios. Nenhuma conta está conectada. Na implantação, a escolha do banco e do provedor definirá a integração; as conferências desta prévia são manuais.</p>`;}
 function finBalanceOrigin(a){return `<details class="fin-balance-origin"><summary>Conferir origem dos saldos</summary>${row('Abertura no extrato',cash(a.openingBalance),'Saldo bancário inicial preservado · '+date(a.openingDate))}${row('Abertura no livro',cash(a.bookOpeningBalance),esc(a.bookOpeningSource))}${a.openingBookAdjustment?row('Diferença entre as aberturas',cash(a.openingBookAdjustment),'Uma alteração anterior ao período continua visível; não é uma conciliação.'):''}${row('Movimentos de caixa do livro',cash(a.bookMovement),'Entradas − saídas, por centavos, nesta conta')}${a.closingPrecisionAdjustment?row('Precisão no fechamento',cash(a.closingPrecisionAdjustment),'Diferença entre o motor e a soma de movimentos arredondados. Não altera extrato, vínculos ou pendências.'):''}${row('Fechamento do livro',cash(a.bookBalance),'Participação desta conta no caixa realizado da operação',true)}</details>`;}
 function finSummary(s){const f=F.ensure(ops),pending=ops.proofs.filter(p=>p.status==='pending');return `<div class="grid2">${panel('O próximo dinheiro a movimentar',s.open.length?s.open.slice().sort((a,b)=>a.due.localeCompare(b.due)).slice(0,5).map(t=>`<div class="fin-due-item"><div>${tag(t.type==='receivable'?'A receber':'A pagar',t.type==='receivable'?'green':'amber')}<h3>${esc(t.description)}</h3><small>${esc(t.counterparty)} · ${date(t.due)} · ${esc(t.vehicle==='company'?'Empresa':t.vehicle)}</small></div><div><strong>${cash(t.amount)}</strong>${btn(t.type==='receivable'?'Conferir entrada':'Conferir saída','fin-pay','',`data-id="${t.id}"`)}</div></div>`).join(''):'<p class="caption">Sem compromissos em aberto.</p>',btn('Ver todos','fin-tab','', 'data-value="titles"'))}${panel('Conferência das contas',s.accounts.map(a=>`<div class="fin-account-summary"><div><strong>${esc(a.name)}</strong><small>Saldo inicial em ${date(a.openingDate)} · ${cash(a.openingBalance)}</small></div>${row('Saldo no extrato',cash(a.bankBalance))}${row('Saldo de caixa atribuído',cash(a.bookBalance))}${row('Diferença a explicar',cash(a.difference),a.unmatchedBank+' do extrato e '+a.unmatchedBook+' do livro sem vínculo',true)}${finBalanceOrigin(a)}</div>`).join(''),btn('Abrir conciliação','fin-tab','','data-value="reconcile"'))}</div><div class="grid2 gap">${panel('Comprovantes aguardando você',pending.length?pending.map(p=>{const t=f.titles.find(t=>t.chargeId===p.chargeId);return row(esc(p.id),tag('Em conferência','amber'),esc(p.note))+(t?btn('Conferir recebimento de '+p.chargeId,'fin-pay','',`data-id="${t.id}"`):'');}).join(''):'<p class="caption">O envio pelo motorista aparece aqui. O caixa muda apenas após sua confirmação.</p>')}${panel('Uma trilha para cada movimento',`<div class="fin-steps"><span><i>1</i>Compromisso<small>Vencimento e responsável</small></span><span><i>2</i>Liquidação<small>Data, conta e livro</small></span><span><i>3</i>Conciliação<small>Vínculo com o extrato</small></span></div><p class="caption gap">Caução é uma garantia a devolver, sem virar receita. Lucro da loja é do motorista; o crédito pode abater o aluguel. Aporte é capital. Principal reduz dívida. Custo de produto já comprado reduz estoque e resultado, sem nova saída de dinheiro. Ganhos pessoais do motorista ficam fora da tesouraria.</p>`)}</div>`;}
 function finTitles(){const f=F.ensure(ops),list=f.titles.filter(t=>finTitleFilter==='all'||finTitleFilter==='open'&&t.status==='open'||finTitleFilter==='payable'&&t.type==='payable'||finTitleFilter==='receivable'&&t.type==='receivable');return panel('Contas a pagar e a receber',`<div class="fin-filter-bar">${[['open','Em aberto'],['payable','A pagar'],['receivable','A receber'],['all','Todo o histórico']].map(([k,l])=>btn(l,'fin-title-filter',finTitleFilter===k?'primary':'',`data-value="${k}"`)).join('')}</div>`+table(['Compromisso','Vencimento','Centro e categoria','Valor','Situação','Ação'],list.map(t=>`<tr><td><strong>${esc(t.description)}</strong><small>${esc(t.counterparty)} · ${esc(t.id)}</small>${t.creditApplied?`<small>Original ${cash(t.originalAmount)} · abatido ${cash(t.creditApplied)} com lucro da loja</small>`:''}</td><td>${date(t.due)}${t.status==='open'&&t.due<F.today?'<small class="fin-out">Vencido no exemplo</small>':''}</td><td>${esc(t.vehicle==='company'?'Empresa':t.vehicle)}<small>${esc(finCategory(t.category))}</small></td><td>${finSigned(t.amount,t.type==='receivable'?'in':'out')}</td><td>${tag(t.status==='settled'?(t.creditApplied>=t.originalAmount?'Quitado por crédito':'Liquidado'):t.status==='cancelled'?'Cancelado':ops.proofs.some(p=>p.chargeId===t.chargeId&&p.status==='pending')?'Comprovante em análise':'Em aberto',t.status==='settled'?'green':t.status==='cancelled'?'':'amber')}${t.entryId?`<small>${esc(t.entryId)} · ${date(t.settledDate)}</small>`:t.openingHistory?'<small>Histórico inicial consolidado no livro</small>':''}</td><td>${t.status==='open'?btn(t.type==='receivable'?'Receber':'Pagar','fin-pay','',`data-id="${t.id}"`)+(t.chargeId?'':btn('Cancelar','fin-cancel','',`data-id="${t.id}"`)):t.entryId?btn('Ver no livro','fin-tab','','data-value="ledger"')+btn('Estornar baixa','settlement-title-reverse','',`data-id="${t.id}"`):'—'}</td></tr>`).join('')||'<tr><td colspan="6">Nenhum título neste filtro.</td></tr>'))+`<div class="notice gap">Criar um título não movimenta caixa. A baixa registra uma única entrada ou saída; estornar uma baixa exige motivo, data e referência, preservando os lançamentos originais.</div>`;}
 function finReconciliation(s){const f=F.ensure(ops);if(!f.accounts.some(a=>a.id===finAccountId))finAccountId=f.accounts[0].id;const a=s.accounts.find(a=>a.id===finAccountId),transactions=f.transactions.filter(t=>t.accountId===finAccountId),book=F.ledger(ops,{accountId:finAccountId,month:3}).filter(e=>!e.match);return `<div class="fin-account-picker">${f.accounts.map(a=>btn(esc(a.name),'fin-account',a.id===finAccountId?'primary':'',`data-id="${a.id}"`)).join('')}${btn('Incluir movimento de exemplo','fin-transaction')}</div><div class="fin-reconcile-strip">${row('Extrato bancário',cash(a.bankBalance),'Saldo inicial + movimentos do extrato')}${row('Livro de caixa atribuído',cash(a.bookBalance),'Saldo inicial + entradas − saídas confirmadas')}${row('Diferença',cash(a.difference),'Saldo igual não prova conciliação; confira os vínculos.',true)}</div>${finBalanceOrigin(a)}${panel('Extrato · movimentos para conferir',table(['Data e referência','Descrição','Movimento','Conferência','Ação'],transactions.map(t=>{const m=f.matches.find(m=>m.active&&m.transactionId===t.id),count=m?0:F.candidates(ops,t.id).length;return `<tr><td>${date(t.date)}<small>${esc(t.reference)}</small></td><td>${esc(t.description)}<small>${esc(t.id)} · ${t.origin==='manual'?'Incluído manualmente no exemplo':'Extrato demonstrativo'}</small></td><td>${finSigned(t.amount,t.direction)}</td><td>${m?tag('Conciliado','green')+`<small>${esc(m.entryId)}</small>`:tag(count>1?count+' opções · conferir':count===1?'1 opção · conferir':'Sem lançamento equivalente','amber')}</td><td>${m?btn('Desfazer vínculo','fin-unmatch','',`data-id="${m.id}"`):btn('Conferir movimento','fin-review','',`data-id="${t.id}"`)}</td></tr>`;}).join('')||'<tr><td colspan="5">Ainda sem movimentos nesta conta.</td></tr>'),tag(a.unmatchedBank+' pendente(s)',a.unmatchedBank?'amber':'green'))}<div class="gap">${panel('No livro, ainda sem vínculo com o extrato',table(['Registro e data','Origem','Valor','Centro'],book.map(e=>`<tr><td>${esc(e.id)}<small>${date(e.date)}</small></td><td>${esc(e.source)}</td><td>${finSigned(e.amount,e.direction)}</td><td>${esc(e.vehicle==='company'?'Empresa':e.vehicle)}</td></tr>`).join('')||'<tr><td colspan="4">Todos os movimentos de caixa deste mês estão vinculados.</td></tr>'))}</div><p class="caption">Conferência 1 para 1, por conta, valor em centavos e sentido. Não há associação automática. Desfazer a conciliação preserva o lançamento e o extrato. Os juros do histórico matemático são arredondados por movimento; o fechamento empresarial preserva sua precisão original.</p>`;}
 function finLedger(){return ledgerView()+`<div class="notice gap">O livro acima é o mesmo usado em Planejado × realizado. Liquidação adiciona um movimento; conciliar só liga esse movimento ao extrato. Registros de CMV sem caixa ficam fora da conciliação bancária.</div>`;}
 function finTitleForm(type){const incoming=type==='receivable',options=F.categories.filter(([key])=>F.direction(key)===(incoming?'in':'out')&&!['capex','rentalRefund','shopHold','shopRefund','incidentRecovery','driverCreditPayout'].includes(key));return `<form id="fin-title-form"><input type="hidden" name="type" value="${type}"><div class="fields">${input('description','Descrição do compromisso','','required maxlength="150" placeholder="Ex.: lavagem do RV-001"')}${input('counterparty',incoming?'Quem vai pagar':'Favorecido ou fornecedor','','required maxlength="100"')}${input('amount','Valor · R$','','type="number" min="0.01" step="0.01" required')}${input('due','Vencimento',F.today,'type="date" required')}${select('category','Natureza financeira',incoming?'rent':'opex',options)}${select('vehicle','Centro de custo',incoming?'RV-001':'company',finVehicleOptions())}${select('driverId','Motorista · obrigatório para caução','',finDriverOptions())}</div><p class="caption gap">O compromisso fica em aberto até você conferir a liquidação. Para adquirir um carro com ativo, dívida e entrada, use Frota e cuidados.</p><div class="form-actions"><button type="submit" class="btn primary">Criar conta ${incoming?'a receber':'a pagar'}</button></div></form>`;}
 function finPaymentForm(t){return `<form id="fin-pay-form"><input type="hidden" name="titleId" value="${t.id}"><div class="notice">${esc(t.description)}<br><strong>${cash(t.amount)}</strong> · ${esc(t.counterparty)}${t.creditApplied?`<br>Aluguel original ${cash(t.originalAmount)} − lucro abatido ${cash(t.creditApplied)} = restante ${cash(t.amount)}`:''}</div><div class="fields gap">${input('date',t.type==='receivable'?'Data do recebimento conferido':'Data do pagamento conferido',F.today,'type="date" min="2027-01-01" max="2027-01-31" required')}${select('accountId','Conta movimentada','BANK-1',finAccountOptions())}</div><p class="caption gap">Confirme depois de conferir o recebimento ou pagamento. A baixa gera um movimento no livro; a conciliação bancária é a etapa seguinte.</p><div class="form-actions"><button type="submit" class="btn primary">Confirmar ${t.type==='receivable'?'recebimento':'pagamento'} no exemplo</button></div></form>`;}
 function finTransactionForm(){return `<form id="fin-transaction-form"><div class="fields">${select('accountId','Conta',finAccountId,finAccountOptions())}${select('direction','Sentido','out',[['in','Entrada'],['out','Saída']])}${input('date','Data do extrato',F.today,'type="date" min="2027-01-01" max="2027-01-31" required')}${input('amount','Valor · R$','','type="number" min="0.01" step="0.01" required')}${input('reference','Referência única do movimento','','required maxlength="100" placeholder="Ex.: TESTE-0001"')}${input('description','Descrição no extrato','','required maxlength="150"')}</div><p class="caption gap">Simula a chegada de um movimento bancário. Incluir no extrato não cria receita ou despesa no livro.</p><div class="form-actions"><button type="submit" class="btn primary">Adicionar ao extrato de exemplo</button></div></form>`;}
 function finReview(t){const matches=F.candidates(ops,t.id),titles=F.titleCandidates(ops,t.id);return `<div class="notice"><strong>${esc(t.description)}</strong><br>${date(t.date)} · ${finSigned(t.amount,t.direction)}<br>${esc(t.reference)}</div>${matches.length?`<p class="caption gap">${matches.length===1?'Confira a origem antes de vincular.':'Existem várias opções com o mesmo valor. Escolha pela origem; nenhuma é vinculada automaticamente.'}</p><div class="gap">${matches.map(e=>`<div class="fin-match-option"><div><strong>${esc(e.id)} · ${cash(e.amount)}</strong><small>${date(e.date)} · ${esc(e.source)} · ${esc(e.vehicle)}</small></div>${btn('Vincular este lançamento','fin-match','primary',`data-transaction="${t.id}" data-entry="${e.id}"`)}</div>`).join('')}</div>`:titles.length?`<p class="caption gap">Há compromisso(s) em aberto com esse valor. Confira pagador, origem e vencimento. A baixa e a conciliação usarão o mesmo lançamento.</p>${titles.map(title=>`<div class="fin-match-option"><div><strong>${esc(title.description)} · ${cash(title.amount)}</strong><small>${esc(title.counterparty)} · ${date(title.due)} · ${esc(title.vehicle)}</small></div>${btn('Baixar título e conciliar','fin-pay-from-statement','primary',`data-transaction="${t.id}" data-title="${title.id}"`)}</div>`).join('')}`:`<p class="caption gap">Não encontramos movimento de caixa com o mesmo valor, sentido e conta. Confira o extrato e os registros antes de criar algo.</p><form id="fin-post-form"><input type="hidden" name="transactionId" value="${t.id}"><div class="fields gap">${select('category','Natureza do novo lançamento',t.direction==='in'?'rent':'opex',F.categories.filter(([key])=>F.direction(key)===t.direction&&!['capex','rentalRefund','shopHold','shopRefund','incidentRecovery','driverCreditPayout'].includes(key)))}${select('vehicle','Centro de custo','company',finVehicleOptions())}${select('driverId','Motorista · obrigatório para caução','',finDriverOptions())}</div><p class="caption gap">Ao confirmar, será criado um único movimento no livro e o vínculo com este extrato. Use para uma tarifa ou entrada ainda ausente; não substitui um título já aberto.</p><div class="form-actions"><button type="submit" class="btn primary">Criar lançamento e conciliar</button></div></form>`}`;}
 function financeAction(action,e){if(!action.startsWith('fin-'))return false;const f=F.ensure(ops);if(action==='fin-tab'){finView=e.dataset.value;render();}else if(action==='fin-title-filter'){finTitleFilter=e.dataset.value;render();}else if(action==='fin-account'){finAccountId=e.dataset.id;render();}else if(action==='fin-new-payable'||action==='fin-new-receivable'){const type=action==='fin-new-payable'?'payable':'receivable';open(type==='payable'?'Nova conta a pagar':'Nova conta a receber',finTitleForm(type));}else if(action==='fin-pay'){const t=f.titles.find(t=>t.id===e.dataset.id);if(!t)throw new RangeError('Título não encontrado.');open(t.type==='receivable'?'Conferir recebimento':'Conferir pagamento',finPaymentForm(t));}else if(action==='fin-cancel'){F.cancelTitle(ops,e.dataset.id);render();persist();toast('Compromisso cancelado; nenhum dinheiro foi movimentado.');}else if(action==='fin-transaction')open('Novo movimento do extrato demonstrativo',finTransactionForm());else if(action==='fin-review'){const t=f.transactions.find(t=>t.id===e.dataset.id);open('Conferir movimento contra o livro',finReview(t));}else if(action==='fin-match'){F.match(ops,e.dataset.transaction,e.dataset.entry);close();render();persist();toast('Vínculo conferido. Nenhum novo lançamento foi criado.');}else if(action==='fin-pay-from-statement'){F.payFromStatement(ops,e.dataset.transaction,e.dataset.title);close();render();persist();toast('Título liquidado e conciliado com um único lançamento.');}else if(action==='fin-unmatch'){F.unmatch(ops,e.dataset.id);render();persist();toast('Conciliação desfeita; extrato e livro foram preservados.');}else return false;return true;}
 function financeSubmit(form,f){if(!form.id.startsWith('fin-'))return false;let message='';if(form.id==='fin-title-form'){F.createTitle(ops,{type:f.get('type'),description:f.get('description'),counterparty:f.get('counterparty'),amount:Number(f.get('amount')),due:f.get('due'),category:f.get('category'),vehicle:f.get('vehicle'),driverId:f.get('driverId')});finView='titles';finTitleFilter='open';message='Compromisso criado. O caixa continua igual até a liquidação.';}else if(form.id==='fin-pay-form'){F.pay(ops,f.get('titleId'),{date:f.get('date'),accountId:f.get('accountId')});message='Liquidação conferida uma vez no livro. Concilie quando aparecer no extrato.';}else if(form.id==='fin-transaction-form'){F.addTransaction(ops,{accountId:f.get('accountId'),direction:f.get('direction'),date:f.get('date'),amount:Number(f.get('amount')),reference:f.get('reference'),description:f.get('description')});finView='reconcile';finAccountId=String(f.get('accountId'));message='Movimento incluído no extrato de exemplo. Livro de caixa preservado.';}else if(form.id==='fin-post-form'){F.postStatement(ops,f.get('transactionId'),{category:f.get('category'),vehicle:f.get('vehicle'),driverId:f.get('driverId')});message='Movimento criado no livro e conciliado uma única vez.';}else return false;close();render();persist();toast(message);return true;}
